# flood components and fill their bbox interiors; color based interior dimensions even=>2, odd=>7
import copy
out=copy.deepcopy(grid); R=len(grid); C=len(grid[0]); seen=set()
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col==6 or (r,c) in seen: continue
  stack=[(r,c)];seen.add((r,c)); pts=[]
  while stack:
   y,x=stack.pop();pts.append((y,x))
   for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
    if 0<=yy<R and 0<=xx<C and (yy,xx) not in seen and grid[yy][xx]==col: seen.add((yy,xx));stack.append((yy,xx))
  a=min(y for y,x in pts);b=max(y for y,x in pts);d=min(x for y,x in pts);e=max(x for y,x in pts)
  if b-a>1 and e-d>1 and all(grid[y][x]==col for y in (a,b) for x in range(d,e+1)) and all(grid[y][x]==col for x in (d,e) for y in range(a,b+1)):
   h=b-a-1;w=e-d-1; fill=7 if h%2 and w%2 else 2
   for y in range(a+1,b):
    for x in range(d+1,e):out[y][x]=fill
print(out)
